package alternate;public class BindingAccess{record Payload(String label){}record Bound(int kind,Object queue){}public static Object payload(String s){return new Payload(s);}public static String[]strings(int n){String[]a=new String[n];java.util.Arrays.fill(a,"PRELOAD");return a;}public static Integer[]integers(int n){Integer[]a=new Integer[n];java.util.Arrays.fill(a,-999);return a;}public static Payload[]payloads(int n){Payload[]a=new Payload[n];java.util.Arrays.fill(a,new Payload("PRELOAD"));return a;}public static Number[]numbers(int n){Number[]a=new Number[n];java.util.Arrays.fill(a,-999.0);return a;}public static Object create(int kind,int n){return new Bound(kind,switch(kind){case 0->{alternate.DynQueue<String>q=new alternate.DynQueue<>(strings(n));yield q;}case 1->{alternate.DynQueue<Integer>q=new alternate.DynQueue<>(integers(n));yield q;}case 2->{alternate.DynQueue<Payload>q=new alternate.DynQueue<>(payloads(n));yield q;}default->{alternate.DynQueue<Number>q=new alternate.DynQueue<>(numbers(n));yield q;}});}@SuppressWarnings("unchecked")public static void put(Object q,Object value){Bound b=(Bound)q;switch(b.kind){case 0->{alternate.DynQueue<String>s=(alternate.DynQueue<String>)b.queue;s.put((String)value);}case 1->{alternate.DynQueue<Integer>s=(alternate.DynQueue<Integer>)b.queue;s.put((Integer)value);}case 2->{alternate.DynQueue<Payload>s=(alternate.DynQueue<Payload>)b.queue;s.put((Payload)value);}default->{alternate.DynQueue<Number>s=(alternate.DynQueue<Number>)b.queue;s.put((Number)value);}}}@SuppressWarnings("unchecked")public static Object get(Object q){Bound b=(Bound)q;return switch(b.kind){case 0->{alternate.DynQueue<String>s=(alternate.DynQueue<String>)b.queue;String value=s.get();yield value;}case 1->{alternate.DynQueue<Integer>s=(alternate.DynQueue<Integer>)b.queue;Integer value=s.get();yield value;}case 2->{alternate.DynQueue<Payload>s=(alternate.DynQueue<Payload>)b.queue;Payload value=s.get();yield value;}default->{alternate.DynQueue<Number>s=(alternate.DynQueue<Number>)b.queue;Number value=s.get();yield value;}};}}
